use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

fn main() {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).expect("clock before 1970");
    println!("seconds since 1970 is more than 1.7 billion: {}", now.as_secs() > 1_700_000_000);

    let start = Instant::now();
    thread::sleep(Duration::from_millis(20));
    let elapsed = start.elapsed();
    println!("slept at least 20 ms: {}", elapsed >= Duration::from_millis(20));

    let d = Duration::from_secs(3725) + Duration::from_millis(250);
    println!("{:?} = {} s = {} ms", d, d.as_secs_f64(), d.as_millis());
    let (h, m, s) = (d.as_secs() / 3600, d.as_secs() / 60 % 60, d.as_secs() % 60);
    println!("{h:02}:{m:02}:{s:02}.{:03}", d.subsec_millis());
    println!("{:?}", Duration::from_secs(1).checked_sub(Duration::from_secs(2)));
}

/// Days since 1970-01-01 to (year, month, day). Works for negative days too.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468; // shift the epoch to 0000-03-01
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097); // day of era [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365; // year of era [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // day of year, March-based [0, 365]
    let mp = (5 * doy + 2) / 153; // month, March = 0
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn rfc3339(unix: i64) -> String {
    let (days, secs) = (unix.div_euclid(86_400), unix.rem_euclid(86_400));
    let (y, m, d) = civil_from_days(days);
    format!("{y:04}-{m:02}-{d:02}T{:02}:{:02}:{:02}Z", secs / 3600, secs / 60 % 60, secs % 60)
}

fn main() {
    for t in [0, 951_782_400, 1_709_211_909, 2_147_483_647, -1] {
        println!("{t:>11} -> {}", rfc3339(t));
    }
}

const NTP_TO_UNIX_SECONDS: u64 = 2_208_988_800;

#[derive(Debug, Clone, Copy, PartialEq)]
struct NtpTimestamp {
    seconds: u32,
    fraction: u32,
}

impl NtpTimestamp {
    fn from_unix(secs: u64, nanos: u32) -> Self {
        let fraction = ((nanos as u64) << 32) / 1_000_000_000;
        NtpTimestamp { seconds: (secs + NTP_TO_UNIX_SECONDS) as u32, fraction: fraction as u32 }
    }

    fn to_unix(self) -> (u64, u32) {
        let nanos = ((self.fraction as u64) * 1_000_000_000) >> 32;
        (self.seconds as u64 - NTP_TO_UNIX_SECONDS, nanos as u32)
    }

    fn to_bytes(self) -> [u8; 8] {
        let mut b = [0u8; 8];
        b[..4].copy_from_slice(&self.seconds.to_be_bytes());
        b[4..].copy_from_slice(&self.fraction.to_be_bytes());
        b
    }
}

fn main() {
    let t = NtpTimestamp::from_unix(1_709_211_909, 500_000_000);
    println!("{t:?}");
    println!("{:02x?}", t.to_bytes());
    println!("{:?}", t.to_unix());
}

