struct NtpResult {
    t1: f64,
    t2: f64,
    t3: f64,
    t4: f64,
}

impl NtpResult {
    fn offset(&self) -> f64 {
        ((self.t2 - self.t1) + (self.t3 - self.t4)) / 2.0
    }

    fn delay(&self) -> f64 {
        (self.t4 - self.t1) - (self.t3 - self.t2)
    }
}

fn weighted_mean(values: &[f64], weights: &[f64]) -> f64 {
    let total: f64 = values.iter().zip(weights).map(|(v, w)| v * w).sum();
    total / weights.iter().sum::<f64>()
}

fn main() {
    // milliseconds; our clock is about 100 ms behind
    let results = [
        NtpResult { t1: 1000.0, t2: 1110.0, t3: 1111.0, t4: 1021.0 },
        NtpResult { t1: 2000.0, t2: 2125.0, t3: 2126.0, t4: 2051.0 },
        NtpResult { t1: 3000.0, t2: 3300.0, t3: 3301.0, t4: 3401.0 },
    ];
    let mut offsets = Vec::new();
    let mut weights = Vec::new();
    for r in &results {
        println!("offset {:>6.1} ms, delay {:>5.1} ms", r.offset(), r.delay());
        offsets.push(r.offset());
        weights.push(1.0 / (r.delay() * r.delay()));
    }
    println!("weighted offset {:.1} ms", weighted_mean(&offsets, &weights));
}

